import itertools

def get_price(seq):
    max_p = 0
    current_sum = 0
    for x in seq:
        current_sum += x
        max_p = max(max_p, abs(current_sum))
    return max_p

def sam_price(nums):
    min_p = float('inf')
    for p in itertools.permutations(nums):
        min_p = min(min_p, get_price(p))
    return min_p

def george_price(nums):
    def get_all_george_sequences(current_nums, current_sum, current_seq):
        if not current_nums:
            return [get_price(current_seq)]

        if not current_seq:
            min_abs = min(abs(x) for x in current_nums)
            choices = [x for x in current_nums if abs(x) == min_abs]
            results = []
            for c in choices:
                # Handle duplicate numbers correctly
                new_nums = list(current_nums)
                new_nums.remove(c)
                results.extend(get_all_george_sequences(new_nums, c, [c]))
            return results
        else:
            min_val = float('inf')
            for x in current_nums:
                min_val = min(min_val, abs(current_sum + x))

            choices = [x for x in current_nums if abs(current_sum + x) == min_val]
            results = []
            for c in choices:
                new_nums = list(current_nums)
                new_nums.remove(c)
                results.extend(get_all_george_sequences(new_nums, current_sum + c, current_seq + [c]))
            return results

    return get_all_george_sequences(list(nums), 0, [])

