def find_min_ratio(m, range_val):
    min_ratio = float('inf')
    best_set = None
    for nums in itertools.product(range(-range_val, range_val+1), repeat=m):
        if all(x == 0 for x in nums): continue
        s_price = sam_price(nums)
        g_prices = george_price(nums)
        for g in g_prices:
            ratio = s_price / g
            if ratio < min_ratio:
                min_ratio = ratio
                best_set = nums
    return min_ratio, best_set

