import itertools
import random

def get_price(seq):
    max_p = 0
    current_sum = 0
    for x in seq:
        current_sum += x
        max_p = max(max_p, abs(current_sum))
    return max_p

def get_george_price(case):
    min_abs = min(abs(x) for x in case)
    min_abs_indices = [i for i in range(len(case)) if abs(case[i]) == min_abs]

    possible_gs = []

    def get_george_sequences(current_indices, current_seq):
        if not current_indices:
            possible_gs.append(get_price(current_seq))
            return

        current_sum = sum(current_seq)
        best_val = float('inf')
        best_indices = []

        for i in current_indices:
            val = abs(current_sum + case[i])
            if val < best_val:
                best_val = val
                best_indices = [i]
            elif val == best_val:
                best_indices.append(i)

        for i in best_indices:
            new_indices = [idx for idx in current_indices if idx != i]
            get_george_sequences(new_indices, current_seq + [case[i]])

    for i in min_abs_indices:
        get_george_sequences([idx for idx in range(len(case)) if idx != i], [case[i]])

    return possible_gs

def find_min_ratio(case):
    s_min = float('inf')
    for p in itertools.permutations(case):
        s_min = min(s_min, get_price(p))

    gs = get_george_price(case)
    min_ratio = float('inf')
    for g in gs:
        min_ratio = min(min_ratio, s_min / g)
    return s_min, gs, min_ratio

